msg.payload = {
    acao: "baixar",
    url: "/baixar/mensal"
};

return msg;

msg.headers = {
    "Content-Type": "text/html; charset=utf-8",
    "Content-Disposition": "attachment; filename=relatorio_mensal.html"
};

return msg;

let arquivos = msg.payload;

if (!Array.isArray(arquivos)) {
    node.error("A resposta do FTP não é uma lista.", msg);
    return null;
}

// Filtra apenas arquivos TXT da estação
let pcd = arquivos.filter(arq => {
    let nome = "";

    if (typeof arq === "string") {
        nome = arq;
    } else if (arq && arq.name) {
        nome = arq.name;
    }

    return nome.startsWith("PCD_PATIO") &&
           nome.toLowerCase().endsWith(".txt");
});

if (pcd.length === 0) {
    node.error("Nenhum arquivo PCD_PATIO encontrado.", msg);
    return null;
}

// Ordena pelo nome
pcd.sort((a, b) => {
    let nomeA = typeof a === "string" ? a : a.name;
    let nomeB = typeof b === "string" ? b : b.name;

    return nomeA.localeCompare(nomeB);
});

// Pega o último
let ultimo = pcd[pcd.length - 1];

let nomeArquivo =
    typeof ultimo === "string"
        ? ultimo
        : ultimo.name;

msg.payload = ultimo;
msg.arquivoFTP = "/" + nomeArquivo;
msg.nomeArquivo = nomeArquivo;

return msg;

if (!msg.arquivoFTP) {
    node.error("Nenhum arquivo FTP foi selecionado.", msg);
    return null;
}

msg.operation = "get";

// caminho remoto escolhido automaticamente pela function 37
msg.filename = msg.arquivoFTP;

// arquivo temporário local
msg.localFilename = "/tmp/agrosynk_atual.txt";

return msg;

// ==========================================
// AGROSYNK - INTERPRETAR TXT DA ESTAÇÃO
// MAPEAMENTO DOS SENSORES
//
// IMPORTANTE:
// Os nomes "umidadeSolo1" e "temperaturaSolo1"
// são mantidos por compatibilidade com o sistema,
// porém representam UMIDADE DO AR e TEMPERATURA DO AR.
// ==========================================

let texto = msg.payload;

// Converte Buffer para texto
if (Buffer.isBuffer(texto)) {
    texto = texto.toString("utf8");
}

// Verifica se o conteúdo é válido
if (typeof texto !== "string") {
    node.error("Conteúdo do TXT inválido.", msg);
    return null;
}

// Divide o arquivo em linhas
let linhas = texto
    .split(/\r?\n/)
    .map(function(linha) {
        return linha.trim();
    })
    .filter(function(linha) {
        return linha.length > 0;
    });

// Precisa existir cabeçalho + pelo menos uma leitura
if (linhas.length < 2) {
    node.error("TXT sem leituras válidas.", msg);
    return null;
}

// Ignora a primeira linha do arquivo
// Exemplo:
// PCD_PATIO;;2026-09-14 23:00:22;...
let linhasDados = linhas.slice(1);

let leituras = [];

// ==========================================
// INTERPRETAR CADA LEITURA
// ==========================================

linhasDados.forEach(function(linha) {

    let dados = linha.split(";");

    // Esperamos 10 campos
    if (dados.length >= 10) {

        leituras.push({

            // --------------------------------
            // ESTAÇÃO
            // --------------------------------

            portaGabinete: Number(dados[0]),

            tensaoBateria: Number(dados[1]),

            temperaturaInterna: Number(dados[2]),

            umidadeInterna: Number(dados[3]),


            // --------------------------------
            // CHUVA
            // --------------------------------

            chuvaAcumulada: Number(dados[4]),


            // --------------------------------
            // SOLO - DADOS REAIS
            // --------------------------------

            umidadeSolo: Number(dados[5]),

            temperaturaSolo: Number(dados[6]),


            // --------------------------------
            // AR - DADOS REAIS
            // --------------------------------
            //
            // ATENÇÃO:
            // Os nomes abaixo são LEGADOS.
            //
            // umidadeSolo1 = UMIDADE DO AR
            // temperaturaSolo1 = TEMPERATURA DO AR
            //
            // Mantemos os nomes para não quebrar
            // banco de dados e outros fluxos.
            // --------------------------------

            umidadeSolo1: Number(dados[7]),

            temperaturaSolo1: Number(dados[8]),


            // --------------------------------
            // DATA / HORA
            // --------------------------------

            dataHora: dados[9]
        });
    }
});

// ==========================================
// VERIFICAÇÃO
// ==========================================

if (leituras.length === 0) {
    node.error(
        "Nenhuma leitura válida encontrada no TXT.",
        msg
    );

    return null;
}

// Todas as leituras do arquivo
msg.leiturasTXT = leituras;

// Última leitura = leitura atual
msg.payload = leituras[leituras.length - 1];

return msg;

let d = msg.payload;

// Dados gerais da estação
flow.set("estacao_portaGabinete", d.portaGabinete);
flow.set("estacao_tensaoBateria", d.tensaoBateria);
flow.set("estacao_temperaturaInterna", d.temperaturaInterna);
flow.set("estacao_umidadeInterna", d.umidadeInterna);
flow.set("estacao_chuvaAcumulada", d.chuvaAcumulada);

// Sensor de solo 0
flow.set("estacao_umidadeSolo", d.umidadeSolo);
flow.set("estacao_temperaturaSolo", d.temperaturaSolo);

// Sensor de solo 1
flow.set("estacao_umidadeSolo1", d.umidadeSolo1);
flow.set("estacao_temperaturaSolo1", d.temperaturaSolo1);

// Horário real da medição
flow.set("estacao_dataHora", d.dataHora);

// Mantém os dados no payload para conferência
msg.payload = d;

return msg;

// ==========================================
// AGROSYNK - HISTÓRICO DE 30 DIAS
//
// MAPEAMENTO:
// umidadeSolo       = UMIDADE DO SOLO
// temperaturaSolo   = TEMPERATURA DO SOLO
//
// umidadeSolo1      = UMIDADE DO AR
// temperaturaSolo1  = TEMPERATURA DO AR
//
// Os nomes "Solo1" são mantidos apenas
// para compatibilidade com o sistema antigo.
// ==========================================

let historico = flow.get("historico30dias") || [];
let novasLeituras = msg.leiturasTXT || [];

// ==========================================
// VERIFICAR LEITURAS
// ==========================================

if (!Array.isArray(novasLeituras) || novasLeituras.length === 0) {
    novasLeituras = msg.payload ? [msg.payload] : [];
}

if (novasLeituras.length === 0) {
    node.error("Nenhuma leitura disponível para salvar.", msg);
    return null;
}


// ==========================================
// FUNÇÃO PARA CONVERTER DATA
// ==========================================

function parseData(dataHora) {

    if (!dataHora || typeof dataHora !== "string") {
        return null;
    }

    let partes = dataHora.trim().split(" ");

    if (partes.length !== 2) {
        return null;
    }

    let data = new Date(partes[0] + "T" + partes[1]);

    if (isNaN(data.getTime())) {
        return null;
    }

    return data;
}


// ==========================================
// ADICIONAR NOVAS LEITURAS
// ==========================================

let adicionadas = 0;
let duplicadas = 0;

novasLeituras.forEach(function(leitura) {

    if (!leitura || !leitura.dataHora) {
        return;
    }

    // Evita duplicação pelo horário da leitura
    let jaExiste = historico.some(function(item) {
        return item.dataHora === leitura.dataHora;
    });

    if (!jaExiste) {

        historico.push({

            // --------------------------------
            // ESTAÇÃO
            // --------------------------------

            portaGabinete: leitura.portaGabinete,

            tensaoBateria: leitura.tensaoBateria,

            temperaturaInterna: leitura.temperaturaInterna,

            umidadeInterna: leitura.umidadeInterna,


            // --------------------------------
            // CHUVA
            // --------------------------------

            chuvaAcumulada: leitura.chuvaAcumulada,


            // --------------------------------
            // SOLO - DADOS REAIS
            // --------------------------------

            umidadeSolo: leitura.umidadeSolo,

            temperaturaSolo: leitura.temperaturaSolo,


            // --------------------------------
            // AR - DADOS REAIS
            //
            // ATENÇÃO:
            // Os nomes Solo1 são LEGADOS.
            // --------------------------------

            umidadeSolo1: leitura.umidadeSolo1,

            temperaturaSolo1: leitura.temperaturaSolo1,


            // --------------------------------
            // DATA / HORA
            // --------------------------------

            dataHora: leitura.dataHora
        });

        adicionadas++;

    } else {

        duplicadas++;
    }
});


// ==========================================
// MANTER SOMENTE OS ÚLTIMOS 30 DIAS
// ==========================================

let agora = new Date();

let limite30Dias = new Date(
    agora.getTime() - (30 * 24 * 60 * 60 * 1000)
);

historico = historico.filter(function(item) {

    let dataItem = parseData(item.dataHora);

    if (dataItem === null) {
        return false;
    }

    return dataItem.getTime() >= limite30Dias.getTime();
});


// ==========================================
// ORDENAR CRONOLOGICAMENTE
// ==========================================

historico.sort(function(a, b) {

    let dataA = parseData(a.dataHora);
    let dataB = parseData(b.dataHora);

    if (dataA === null || dataB === null) {
        return 0;
    }

    return dataA.getTime() - dataB.getTime();
});


// ==========================================
// SALVAR HISTÓRICO NO FLOW
// ==========================================

flow.set("historico30dias", historico);


// ==========================================
// INFORMAÇÕES PARA OS PRÓXIMOS NÓS
// ==========================================

msg.historico30dias = historico;

msg.totalLeituras30Dias = historico.length;

msg.leiturasAdicionadas = adicionadas;

msg.leiturasDuplicadas = duplicadas;


// Mantém a leitura mais recente no payload
if (novasLeituras.length > 0) {
    msg.payload = novasLeituras[novasLeituras.length - 1];
}

return msg;

// ==========================================
// AGROSYNK - PREPARAR INSERT POSTGRESQL
// ESTRUTURA ORIGINAL MANTIDA
//
// IMPORTANTE:
// umidadeSolo1 = UMIDADE DO AR
// temperaturaSolo1 = TEMPERATURA DO AR
//
// Os nomes antigos são mantidos para
// compatibilidade com o banco de dados.
// ==========================================

let leituras = msg.leiturasTXT || [];

// Verifica se existem leituras
if (!Array.isArray(leituras) || leituras.length === 0) {

    node.error(
        "Nenhuma leitura disponível para inserir no PostgreSQL.",
        msg
    );

    return null;
}

// ==========================================
// PREPARAR DADOS PARA O BANCO
// ==========================================

let dadosBanco = leituras.map(function(leitura) {

    return {

        // Data e hora
        data_hora: leitura.dataHora,

        // Estação
        porta_gabinete: leitura.portaGabinete,
        tensao_bateria: leitura.tensaoBateria,

        temperatura_interna: leitura.temperaturaInterna,
        umidade_interna: leitura.umidadeInterna,

        // Chuva
        chuva_acumulada: leitura.chuvaAcumulada,

        // ==================================
        // SOLO - DADOS REAIS
        // ==================================

        umidade_solo: leitura.umidadeSolo,
        temperatura_solo: leitura.temperaturaSolo,

        // ==================================
        // AR - DADOS REAIS
        // ==================================
        //
        // Apesar do nome "_solo_1" no banco:
        //
        // umidade_solo_1 = UMIDADE DO AR
        // temperatura_solo_1 = TEMPERATURA DO AR
        //
        // Mantido assim para compatibilidade.
        // ==================================

        umidade_solo_1: leitura.umidadeSolo1,
        temperatura_solo_1: leitura.temperaturaSolo1
    };
});

// Converte o conjunto de leituras para JSON
// que será enviado ao PostgreSQL
msg.params = [
    JSON.stringify(dadosBanco)
];

return msg;

// ==========================================
// AGROSYNK - RESTAURAR HISTÓRICO DO POSTGRESQL
// ==========================================

let dados = msg.payload;

if (!Array.isArray(dados)) {
    node.error("Histórico recebido do PostgreSQL é inválido.", msg);
    return null;
}

let historico = dados.map(function(item) {

    // PostgreSQL pode retornar a data como objeto Date
    let dataHora;

    if (item.data_hora instanceof Date) {
        dataHora = item.data_hora
            .toISOString()
            .replace("T", " ")
            .substring(0, 19);
    } else {
        dataHora = String(item.data_hora)
            .replace("T", " ")
            .replace("Z", "")
            .substring(0, 19);
    }

    return {
        portaGabinete: item.porta_gabinete,
        tensaoBateria: item.tensao_bateria,
        temperaturaInterna: item.temperatura_interna,
        umidadeInterna: item.umidade_interna,
        chuvaAcumulada: item.chuva_acumulada,

        umidadeSolo: item.umidade_solo,
        temperaturaSolo: item.temperatura_solo,

        umidadeSolo1: item.umidade_solo_1,
        temperaturaSolo1: item.temperatura_solo_1,

        dataHora: dataHora
    };
});

flow.set("historico30dias", historico);

// Para conferirmos no Debug
msg.payload = historico;
msg.historico30dias = historico;
msg.totalLeituras30Dias = historico.length;
msg.historicoRestaurado = true;

return msg;

// ==========================================
// AGROSYNK - CALCULAR CHUVA DE HOJE
// ==========================================

// Recupera o histórico
let historico = flow.get("historico30dias") || [];

// Verifica se existe histórico
if (!Array.isArray(historico) || historico.length === 0) {
    flow.set("chuvaHoje", 0);

    msg.payload = 0;
    msg.topic = "Chuva Hoje";

    return msg;
}


// ==========================================
// DATA ATUAL
// ==========================================

let agora = new Date();

let anoHoje = agora.getFullYear();
let mesHoje = agora.getMonth();
let diaHoje = agora.getDate();


// ==========================================
// PROCURA PRIMEIRA E ÚLTIMA LEITURA DE HOJE
// ==========================================

let primeiraData = null;
let ultimaData = null;

let primeiraChuva = null;
let ultimaChuva = null;


for (let i = 0; i < historico.length; i++) {

    let leitura = historico[i];

    if (!leitura.dataHora) {
        continue;
    }

    // Converte:
    // 2026-09-15 14:30:00
    // para:
    // 2026-09-15T14:30:00

    let textoData = leitura.dataHora.toString().replace(" ", "T");

    let dataLeitura = new Date(textoData);

    if (isNaN(dataLeitura.getTime())) {
        continue;
    }


    // Verifica se a leitura pertence ao dia de hoje
    let ehHoje =
        dataLeitura.getFullYear() === anoHoje &&
        dataLeitura.getMonth() === mesHoje &&
        dataLeitura.getDate() === diaHoje;


    if (!ehHoje) {
        continue;
    }


    let chuva = Number(leitura.chuvaAcumulada);

    if (isNaN(chuva)) {
        continue;
    }


    // Primeira leitura encontrada
    if (
        primeiraData === null ||
        dataLeitura.getTime() < primeiraData.getTime()
    ) {

        primeiraData = dataLeitura;
        primeiraChuva = chuva;
    }


    // Última leitura encontrada
    if (
        ultimaData === null ||
        dataLeitura.getTime() > ultimaData.getTime()
    ) {

        ultimaData = dataLeitura;
        ultimaChuva = chuva;
    }
}


// ==========================================
// VERIFICA SE ENCONTROU LEITURAS
// ==========================================

if (
    primeiraChuva === null ||
    ultimaChuva === null
) {

    flow.set("chuvaHoje", 0);

    msg.payload = 0;
    msg.topic = "Chuva Hoje";

    return msg;
}


// ==========================================
// CALCULA CHUVA DO DIA
// ==========================================

let chuvaHoje = ultimaChuva - primeiraChuva;


// Proteção contra reinício do acumulador
if (chuvaHoje < 0) {
    chuvaHoje = 0;
}


// Uma casa decimal
chuvaHoje = Number(chuvaHoje.toFixed(1));


// ==========================================
// SALVA NO FLOW
// ==========================================

flow.set("chuvaHoje", chuvaHoje);


// ==========================================
// DEBUG / SAÍDA
// ==========================================

msg.payload = chuvaHoje;

msg.topic = "Chuva Hoje";

msg.primeiraLeitura = {
    horario: primeiraData,
    acumulado: primeiraChuva
};

msg.ultimaLeitura = {
    horario: ultimaData,
    acumulado: ultimaChuva
};

return msg;
